def number_of_subarrays(nums, k):
    n = len(nums)
    count = 0
    for i in range(n):
        odd = 0
        for j in range(i, n):
            if nums[j] % 2 == 1:
                odd += 1
            if odd == k:                       # recheck the whole subarray's odd count
                count += 1
    return count

