    static int numberOfSubarrays(int[] nums, int k) {
        int n = nums.length, count = 0;
        for (int i = 0; i < n; i++) {
            int odd = 0;
            for (int j = i; j < n; j++) {
                if (nums[j] % 2 == 1) odd++;
                if (odd == k) count++;               // recheck the whole subarray
            }
        }
        return count;
    }
}

