import java.util.*;

public class Main {
    static int numberOfSubarrays(int[] nums, int k) {
        Map<Integer, Integer> count = new HashMap<>();
        count.put(0, 1);
        int odd = 0, result = 0;
        for (int x : nums) {
            odd += x % 2;                             // running count of odd numbers so far
            result += count.getOrDefault(odd - k, 0);   // subarrays ending here with exactly k odds
            count.merge(odd, 1, Integer::sum);
        }
        return result;
    }
}

