#include <bits/stdc++.h>
using namespace std;

int numberOfSubarrays(vector<int>& nums, int k) {
    unordered_map<int,int> count;
    count[0] = 1;
    int odd = 0, result = 0;
    for (int x : nums) {
        odd += x % 2;                                  // running count of odd numbers so far
        auto it = count.find(odd - k);
        if (it != count.end()) result += it->second;    // subarrays ending here with exactly k odds
        count[odd]++;
    }
    return result;
}
